replacements.from:
display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 36px;

replacements.to:
position: absolute;
  width: 100%;
  height: 100%;
  left: 0;
  top: 0;
  opacity: 0;
  background-color: getCssVar('overlay-color', 'lighter');

replacements.from:
display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;

replacements.to:
border: 1px solid getCssVar('border-color');
  border-radius: 6px;
  backdrop-filter: blur(8px);
  box-shadow: 0 0 24px rgba(0,0,0,0.15);

replacements.from:
position: absolute;
  top: 6px;
  right: 6px;
  width: 22px;
  height: 22px;

replacements.to:
position: absolute;
  width: 100%;
  height: 100%;
  left: 0;
  top: 0;
